// ROS 2 -> DRM fake-input round-trip.
//
// Includes the DRM-generated Rust codec for translated ROS 2 topics and
// round-trips synthetic ("fake") values through encode -> bytes -> decode,
// asserting field equality. This is the "give fake inputs and see how they
// work in DRM" check for the translated set.
//
// Generated sources (produced by `drm build` on tests/ros2_compat/translated):
//   .drm/gen/rust/<pkg>/<topic>/target.rs  (@generated by drm codegen)
//
// The generated module exposes `SAMPLE_MAX`, `encode` and `decode` at module
// level (free functions), so each topic is wired with its own paths.

#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/std_msgs/bool/target.rs"]
mod std_bool;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/std_msgs/int32/target.rs"]
mod std_int32;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/std_msgs/string/target.rs"]
mod std_string;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/std_msgs/header/target.rs"]
mod std_header;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/geometry_msgs/twist/target.rs"]
mod geo_twist;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/geometry_msgs/pose/target.rs"]
mod geo_pose;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/geometry_msgs/pose_stamped/target.rs"]
mod geo_pose_stamped;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/geometry_msgs/transform_stamped/target.rs"]
mod geo_transform_stamped;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/sensor_msgs/imu/target.rs"]
mod sensor_imu;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/sensor_msgs/laser_scan/target.rs"]
mod sensor_laser_scan;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/sensor_msgs/compressed_image/target.rs"]
mod sensor_compressed_image;
#[path = "/root/projects/drm/tests/ros2_compat/translated/.drm/gen/rust/demos/chatter/target.rs"]
mod demo_chatter;

/// Adapter over a generated topic module's `encode`/`decode` free functions.
trait Codec: Clone + PartialEq {
    /// Encoded bytes for a round-trip of `self`.
    fn roundtrip(&self) -> Option<Self>;
}

macro_rules! codec {
    ($ty:ty, $enc:path, $dec:path, $cap:expr) => {
        impl Codec for $ty {
            fn roundtrip(&self) -> Option<Self> {
                let mut buf = vec![0u8; $cap];
                match $enc(self, &mut buf) {
                    Some(n) => $dec(&buf[..n]),
                    None => None,
                }
            }
        }
    };
}

codec!(
    std_bool::StdMsgsBool,
    std_bool::encode,
    std_bool::decode,
    std_bool::SAMPLE_MAX
);
codec!(
    std_int32::StdMsgsInt32,
    std_int32::encode,
    std_int32::decode,
    std_int32::SAMPLE_MAX
);
codec!(
    std_string::StdMsgsString,
    std_string::encode,
    std_string::decode,
    std_string::SAMPLE_MAX
);
codec!(
    std_header::StdMsgsHeader,
    std_header::encode,
    std_header::decode,
    std_header::SAMPLE_MAX
);
codec!(
    geo_twist::GeometryMsgsTwist,
    geo_twist::encode,
    geo_twist::decode,
    geo_twist::SAMPLE_MAX
);
codec!(
    geo_pose::GeometryMsgsPose,
    geo_pose::encode,
    geo_pose::decode,
    geo_pose::SAMPLE_MAX
);
codec!(
    geo_pose_stamped::GeometryMsgsPoseStamped,
    geo_pose_stamped::encode,
    geo_pose_stamped::decode,
    geo_pose_stamped::SAMPLE_MAX
);
codec!(
    geo_transform_stamped::GeometryMsgsTransformStamped,
    geo_transform_stamped::encode,
    geo_transform_stamped::decode,
    geo_transform_stamped::SAMPLE_MAX
);
codec!(
    sensor_imu::SensorMsgsImu,
    sensor_imu::encode,
    sensor_imu::decode,
    sensor_imu::SAMPLE_MAX
);
codec!(
    sensor_laser_scan::SensorMsgsLaserScan,
    sensor_laser_scan::encode,
    sensor_laser_scan::decode,
    sensor_laser_scan::SAMPLE_MAX
);
codec!(
    sensor_compressed_image::SensorMsgsCompressedImage,
    sensor_compressed_image::encode,
    sensor_compressed_image::decode,
    sensor_compressed_image::SAMPLE_MAX
);
codec!(
    demo_chatter::DemosChatter,
    demo_chatter::encode,
    demo_chatter::decode,
    demo_chatter::SAMPLE_MAX
);

/// Checks one fake value against the generated codec and reports the verdict.
fn check<T: Codec>(label: &str, value: T, pass: &mut u32, fail: &mut u32) {
    match value.roundtrip() {
        Some(back) if back == value => {
            println!("{label:<34} roundtrip OK");
            *pass += 1;
        }
        Some(_) => {
            println!("{label:<34} roundtrip MISMATCH");
            *fail += 1;
        }
        None => {
            println!("{label:<34} roundtrip FAILED (encode/decode rejected)");
            *fail += 1;
        }
    }
}

fn main() {
    let mut pass = 0u32;
    let mut fail = 0u32;

    let mut v = std_bool::StdMsgsBool::default();
    v.data = 1;
    check("std_msgs/Bool", v, &mut pass, &mut fail);

    let mut v = std_int32::StdMsgsInt32::default();
    v.data = -123_456;
    check("std_msgs/Int32", v, &mut pass, &mut fail);

    let mut v = std_string::StdMsgsString::default();
    let text = b"Hello World: 42";
    v.data_len = text.len() as u32;
    v.data[..text.len()].copy_from_slice(text);
    check("std_msgs/String (bounded 256)", v, &mut pass, &mut fail);

    let mut v = std_header::StdMsgsHeader::default();
    v.stamp_sec = 1_700_000_000;
    v.stamp_nanosec = 123_456_789;
    let frame = b"base_link";
    v.frame_id_len = frame.len() as u32;
    v.frame_id[..frame.len()].copy_from_slice(frame);
    check("std_msgs/Header", v, &mut pass, &mut fail);

    let mut v = geo_twist::GeometryMsgsTwist::default();
    v.linear_x = 1.5;
    v.linear_y = -0.25;
    v.angular_z = 0.75;
    check("geometry_msgs/Twist", v, &mut pass, &mut fail);

    let mut v = geo_pose::GeometryMsgsPose::default();
    v.position_x = 1.0;
    v.position_z = -3.5;
    v.orientation_w = 1.0;
    check("geometry_msgs/Pose", v, &mut pass, &mut fail);

    let mut v = geo_pose_stamped::GeometryMsgsPoseStamped::default();
    v.stamp_sec = 42;
    v.position_y = 2.5;
    v.orientation_w = 1.0;
    let frame = b"map";
    v.frame_id_len = frame.len() as u32;
    v.frame_id[..frame.len()].copy_from_slice(frame);
    check("geometry_msgs/PoseStamped", v, &mut pass, &mut fail);

    let mut v = geo_transform_stamped::GeometryMsgsTransformStamped::default();
    v.stamp_nanosec = 7;
    v.translation_x = 0.5;
    v.rotation_w = 1.0;
    let frame = b"base_link";
    v.frame_id_len = frame.len() as u32;
    v.frame_id[..frame.len()].copy_from_slice(frame);
    let child = b"laser";
    v.child_frame_id_len = child.len() as u32;
    v.child_frame_id[..child.len()].copy_from_slice(child);
    check("geometry_msgs/TransformStamped", v, &mut pass, &mut fail);

    let mut v = sensor_imu::SensorMsgsImu::default();
    v.linear_acceleration_x = 0.02;
    v.linear_acceleration_z = 9.81;
    v.orientation_w = 1.0;
    v.orientation_covariance[0] = -1.0;
    let frame = b"imu_link";
    v.frame_id_len = frame.len() as u32;
    v.frame_id[..frame.len()].copy_from_slice(frame);
    check("sensor_msgs/Imu", v, &mut pass, &mut fail);

    let mut v = sensor_laser_scan::SensorMsgsLaserScan::default();
    v.angle_min = -1.57;
    v.angle_max = 1.57;
    v.angle_increment = 0.785;
    v.range_max = 30.0;
    v.ranges_len = 4;
    v.ranges[..4].copy_from_slice(&[1.0, 2.5, 3.0, 0.5]);
    v.intensities_len = 4;
    v.intensities[..4].copy_from_slice(&[10.0, 20.0, 30.0, 40.0]);
    check("sensor_msgs/LaserScan (4 beams)", v, &mut pass, &mut fail);

    let mut v = sensor_compressed_image::SensorMsgsCompressedImage::default();
    let fmt = b"jpeg";
    v.format_len = fmt.len() as u32;
    v.format[..fmt.len()].copy_from_slice(fmt);
    v.data_len = 8;
    v.data[..8].copy_from_slice(&[0xFF, 0xD8, 0xFF, 0xE0, 0x00, 0x01, 0x02, 0x03]);
    check("sensor_msgs/CompressedImage", v, &mut pass, &mut fail);

    let mut v = demo_chatter::DemosChatter::default();
    let text = b"Hello World: 1";
    v.data_len = text.len() as u32;
    v.data[..text.len()].copy_from_slice(text);
    check("demos/chatter (talker)", v, &mut pass, &mut fail);

    println!("ROS2_ROUNDTRIP pass={pass} fail={fail}");
    if fail != 0 {
        std::process::exit(1);
    }
}
